    idealAnswerHi: "\u0935\u0947\u0915\u094d\u091f\u0930 \u0938\u0930\u094d\u091a \u0915\u0947 \u0938\u093e\u0925-\u0938\u093e\u0925 \u092b\u093c\u093f\u0932\u094d\u091f\u0930 \u0932\u0917\u093e\u0928\u093e\u2014\u091c\u0948\u0938\u0947 \u0938\u093f\u0930\u094d\u092b 'HR' \u0921\u093f\u092a\u093e\u0930\u094d\u091f\u092e\u0947\u0902\u091f \u092f\u093e '2024' \u0915\u0947 \u092c\u093e\u0926 \u0915\u0940 \u092b\u093e\u0907\u0932\u094b\u0902 \u092e\u0947\u0902 \u0939\u0940 \u0938\u0930\u094d\u091a \u0915\u0930\u0928\u093e\u0964 \u0907\u0938\u0938\u0947 \u0938\u093f\u0915\u094d\u092f\u094b\u0930\u093f\u091f\u0940 \u0914\u0930 \u0938\u0930\u094d\u091a \u0938\u094d\u092a\u0940\u0921 \u0926\u094b\u0928\u094b\u0902 \u092c\u0922\u093c\u0924\u0940 \u0939\u0948\u0902\u0964",
