    idealAnswerHi: "\u092f\u0939 \u0926\u094b-\u091a\u0930\u0923\u0940\u092f \u0938\u0930\u094d\u091a \u0939\u0948: \u092a\u0939\u0932\u0947 \u0924\u0947\u091c \u0935\u0947\u0915\u094d\u091f\u0930 \u0938\u0930\u094d\u091a \u0938\u0947 \u091f\u0949\u092a 25 \u0930\u093f\u091c\u0932\u094d\u091f\u094d\u0938 \u0932\u093e\u0924\u0947 \u0939\u0948\u0902, \u092b\u093f\u0930 \u090f\u0915 \u0915\u094d\u0930\u0949\u0938-\u090f\u0928\u094d\u0915\u094b\u0921\u0930 (Reranker) \u0909\u0928 25 \u0915\u094b \u0917\u0939\u0930\u093e\u0908 \u0938\u0947 \u092a\u0930\u0916\u0915\u0930 \u0938\u092c\u0938\u0947 \u0938\u091f\u0940\u0915 \u091f\u0949\u092a 3 \u0930\u093f\u091c\u0932\u094d\u091f\u094d\u0938 \u091b\u093e\u0902\u091f\u0924\u093e \u0939\u0948\u0964",
