    questionHi: "AI \u0910\u092a \u092e\u0947\u0902 \u091c\u094d\u092f\u093e\u0926\u093e \u0932\u0947\u091f\u0947\u0902\u0938\u0940 \u0915\u093e \u0915\u094d\u092f\u093e \u0915\u093e\u0930\u0923 \u0939\u094b\u0924\u093e \u0939\u0948 \u0914\u0930 \u0907\u0938\u0947 \u0915\u0948\u0938\u0947 \u0915\u092e \u0915\u0930\u0947\u0902\u0917\u0947?",
    category: 'AI Application Development',
